  const trailing = original.match(
    /^(.+),\s+(before|after|when)\s+([^,.!?;]+)([.!?])$/i,
  );
  if (
    trailing &&
    wordCount(trailing[1]) >= 3 &&
    wordCount(trailing[3]) >= 3 &&
    !/^["“']/.test(trailing[1])
