  sentence: string,
): Array<{ word: string; from: number; to: number; available: boolean }> {
  return [...sentence.matchAll(/\p{L}+(?:['’]\p{L}+)?/gu)].map((m) => ({
    word: m[0],
    from: m.index!,
    to: m.index! + m[0].length,
